const m_validate = (() => {
// MY GYM London: checks what a visitor sent against the form definition (forms.mjs). Pure code, no network.
// The browser checks the same things for convenience, but this is the check that counts: nothing reaches the database unless it passes.
// Only fields named in the definition are kept; everything else is dropped. Text is trimmed, control characters removed, lengths limited.

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const PHONE = /^[0-9 +()\-]{7,25}$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;
const META_MAX = { utm_source: 80, utm_medium: 80, utm_campaign: 120, page_url: 300, offer_name: 100 };

const clean = (v, max) => String(v ?? "").replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, "").replace(/\s+$/g, "").replace(/^\s+/g, "").slice(0, max);
const asList = (v) => (Array.isArray(v) ? v : v === undefined || v === null || v === "" ? [] : [v]);
const addDays = (iso, n) => { const d = new Date(iso + "T12:00:00Z"); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const validDate = (s) => DATE.test(s) && !Number.isNaN(Date.parse(s + "T12:00:00Z")) && addDays(s, 0) === s;
function ageOn(dob, today) {
  const [by, bm, bd] = dob.split("-").map(Number), [ty, tm, td] = today.split("-").map(Number);
  let a = ty - by; if (tm < bm || (tm === bm && td < bd)) a--; return a;
}

/** today is 'YYYY-MM-DD' (London). Returns { ok, errors: [{field, message}], data, meta, consent }. */
function validate(form, input, today) {
  const errors = [], data = {}, meta = {}, consent = {};
  const raw = input && typeof input === "object" ? input : {};
  const rawConsent = raw.consent && typeof raw.consent === "object" ? raw.consent : {};
  const rawData = raw.data && typeof raw.data === "object" ? raw.data : {};
  const bad = (field, label, why) => errors.push({ field, message: `${label}: ${why}` });

  for (const f of form.fields) {
    const v = rawData[f.id];
    const label = f.label || f.id;
    if (f.type === "hidden") { if (v !== undefined && META_MAX[f.id]) meta[f.id] = clean(v, META_MAX[f.id]); continue; }
    if (f.type === "checkbox-group") {
      const list = asList(v).map((x) => clean(x, 60)).filter(Boolean);
      if (list.some((x) => !f.options.includes(x))) { bad(f.id, label, "choose from the list"); continue; }
      if (f.required && !list.length) { bad(f.id, label, "please choose at least one"); continue; }
      if (list.length) data[f.id] = list; continue;
    }
    if (Array.isArray(v)) { bad(f.id, label, "one answer only"); continue; }
    const s = clean(v, f.type === "textarea" ? (f.max || 1500) : (f.max || 200));
    if (!s) { if (f.required) bad(f.id, label, "this is required"); continue; }
    if (f.max && String(v ?? "").trim().length > f.max + 50) { bad(f.id, label, "too long"); continue; }
    switch (f.type) {
      case "email": if (!EMAIL.test(s)) { bad(f.id, label, "enter a valid email address"); break; } data[f.id] = s.toLowerCase(); break;
      case "tel": if (!PHONE.test(s)) { bad(f.id, label, "enter a valid phone number"); break; } data[f.id] = s; break;
      case "select": if (f.options && !f.options.includes(s)) { bad(f.id, label, "choose from the list"); break; } data[f.id] = s; break;
      case "radio": if (!f.options.includes(s)) { bad(f.id, label, "choose from the list"); break; } data[f.id] = s; break;
      case "rating": { const n = Number(s); if (!Number.isInteger(n) || n < (f.min || 1) || n > (f.max || 5)) { bad(f.id, label, "choose a rating"); break; } data[f.id] = n; break; }
      case "date": {
        if (!validDate(s)) { bad(f.id, label, "enter a valid date"); break; }
        if (f.minDays !== undefined && s < addDays(today, f.minDays)) { bad(f.id, label, "that date is too soon"); break; }
        if (f.maxDays !== undefined && s > addDays(today, f.maxDays)) { bad(f.id, label, "that date is too far ahead"); break; }
        if (f.ageMin !== undefined) { const a = ageOn(s, today); if (a < f.ageMin || a > f.ageMax) { bad(f.id, label, `Kids Gym is for ages ${f.ageMin} to ${f.ageMax}`); break; } }
        data[f.id] = s; break;
      }
      default: data[f.id] = s;
    }
  }
  for (const c of form.consents || []) {
    const on = rawConsent[c.id] === true || rawConsent[c.id] === "1" || rawConsent[c.id] === "on";
    if (c.required && !on) errors.push({ field: "consent_" + c.id, message: "Please tick: " + c.text.slice(0, 90) });
    if (on) consent[c.id] = true;
  }
  if (form.consentIfFilled && data[form.consentIfFilled.field] && !consent[form.consentIfFilled.consent]) errors.push({ field: "consent_" + form.consentIfFilled.consent, message: form.consentIfFilled.message });
  return { ok: errors.length === 0, errors, data, meta, consent };
}

return { validate };
})();

const m_tokens = (() => {
// MY GYM London: signed links for "confirm my email" and "unsubscribe". Stateless: nothing is stored, so a link in an old email keeps working.
// token = base64url(email) + "." + first 32 hex of HMAC-SHA256(secret, purpose + ":" + email). Purposes: "confirm" and "unsubscribe" (a confirm link cannot unsubscribe, and vice versa).
// Uses only Web Crypto, which both Deno (Edge Functions) and Node have.

const enc = new TextEncoder();
const b64u = (bytes) => btoa(String.fromCharCode(...bytes)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
const fromB64u = (s) => Uint8Array.from(atob(s.replace(/-/g, "+").replace(/_/g, "/")), (c) => c.charCodeAt(0));
const hex = (buf) => Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");

async function mac(secret, purpose, email) {
  const key = await crypto.subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return hex(await crypto.subtle.sign("HMAC", key, enc.encode(purpose + ":" + email))).slice(0, 32);
}

async function makeToken(secret, purpose, email) {
  if (!secret || secret.length < 16) throw new Error("token secret missing or too short");
  const e = String(email).trim().toLowerCase();
  return b64u(enc.encode(e)) + "." + (await mac(secret, purpose, e));
}

/** Returns the email if the token is genuine for this purpose, otherwise null. */
async function checkToken(secret, purpose, token) {
  try {
    if (!secret || secret.length < 16) return null;
    const [p1, sig] = String(token ?? "").split(".");
    if (!p1 || !sig || sig.length !== 32) return null;
    const email = new TextDecoder().decode(fromB64u(p1));
    const want = await mac(secret, purpose, email);
    let diff = 0;
    for (let i = 0; i < 32; i++) diff |= want.charCodeAt(i) ^ sig.charCodeAt(i);
    return diff === 0 && /^[^\s@]+@[^\s@]+$/.test(email) ? email : null;
  } catch { return null; }
}

return { makeToken, checkToken };
})();

const render = m_render.render;
const templates = m_render.templates;
const requiredVars = m_render.requiredVars;
const GLOBALS = m_render.GLOBALS;
const forms = m_forms.default;
const validate = m_validate.validate;
const SETTINGS = m_settings.SETTINGS;
const makeToken = m_tokens.makeToken;
const checkToken = m_tokens.checkToken;

// ---- logic ----
// MY GYM London: what happens when someone sends a form. No network in here: the database and the mailer are passed in, so tests can fake them.
// Order: unknown form -> bot traps -> login -> rate limit -> validation -> store -> consent -> emails (emails never undo a stored submission).

interface Deps {
  now: Date;
  countByIp(formId: string, ipHash: string, sinceISO: string): Promise<number>;
  countByUser(formId: string, userId: string, sinceISO: string): Promise<number>;
  insertSubmission(row: Record<string, unknown>): Promise<string>;
  upsertConsent(row: Record<string, unknown>): Promise<void>;
  getConsent(email: string): Promise<{ confirmed_at: string | null; withdrawn_at: string | null } | null>;
  profileName(userId: string): Promise<string>;
  token(purpose: "confirm" | "unsubscribe", email: string): Promise<string>;
  send(mail: { template: string; to: string; vars: Record<string, string>; replyTo?: string }): Promise<void>;
}
interface Input { form_id?: string; data?: unknown; consent?: unknown; hp?: unknown; elapsed?: unknown; }
interface Ctx { ipHash: string; user: { id: string; email: string } | null; functionsUrl: string; }
interface Result { status: number; body: Record<string, unknown>; }

const ADMIN_EMAIL = "info@mygymlondon.co.uk";
const ADMIN_URL = "https://admin.mygymlondon.co.uk/";
const londonDate = (d: Date) => new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/London", year: "numeric", month: "2-digit", day: "2-digit" }).format(d);
const niceDate = (iso: string) => new Intl.DateTimeFormat("en-GB", { timeZone: "UTC", weekday: "long", day: "numeric", month: "long" }).format(new Date(iso + "T12:00:00Z"));
const firstWord = (s: string) => (String(s).trim().split(/\s+/)[0] || "there");
const addDays = (iso: string, n: number) => { const d = new Date(iso + "T12:00:00Z"); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };

const LABELS: Record<string, string> = { full_name: "Name", parent_name: "Parent", email: "Email", phone: "Phone", topic: "Topic", goal: "Goal", experience: "Experience", times: "Best times", health_note: "Health note", class: "Class", date: "Day", company: "Company", team_size: "Team size", days: "Days", child_first_name: "Child first name", child_last_name: "Child last name", child_dob: "Child date of birth", emergency_name: "Emergency contact", emergency_phone: "Emergency phone", medical: "Medical", message: "Message" };
const SKIP = new Set(["full_name", "parent_name", "email", "phone", "message"]);

function summary(data: Record<string, unknown>): string {
  if (typeof data.message === "string" && Object.keys(data).filter((k) => !SKIP.has(k)).length === 0) return data.message;
  const lines = Object.entries(data).filter(([k]) => !SKIP.has(k)).map(([k, v]) => `${LABELS[k] ?? k}: ${Array.isArray(v) ? v.join(", ") : v}`);
  if (typeof data.message === "string") lines.push("Message: " + data.message);
  return lines.join("\n");
}

async function processSubmission(input: Input, ctx: Ctx, d: Deps): Promise<Result> {
  const form = (forms as Record<string, unknown>[]).find((f) => f.id === input?.form_id) as any;
  if (!form) return { status: 404, body: { ok: false, error: "Unknown form." } };

  // bot traps: a filled hidden field is a robot (pretend it worked, store nothing); sent faster than a person can type
  if (typeof input.hp === "string" && input.hp.trim() !== "") return { status: 200, body: { ok: true, message: form.success } };
  const elapsed = Number(input.elapsed);
  if (!Number.isFinite(elapsed) || elapsed < form.minSeconds) return { status: 429, body: { ok: false, error: "Please take a moment and try again." } };

  if (form.requiresLogin && !ctx.user) return { status: 401, body: { ok: false, error: "Please sign in and try again." } };

  const hourAgo = new Date(d.now.getTime() - 3600_000).toISOString();
  if ((await d.countByIp(form.id, ctx.ipHash, hourAgo)) >= (form.rateLimit?.perIpHour ?? form.rateLimit?.perIpPerHour ?? 5)) return { status: 429, body: { ok: false, error: "Too many messages from this connection. Please try again later." } };
  if (ctx.user && form.rateLimit?.perUserPerDay) {
    const dayAgo = new Date(d.now.getTime() - 86400_000).toISOString();
    if ((await d.countByUser(form.id, ctx.user.id, dayAgo)) >= form.rateLimit.perUserPerDay) return { status: 429, body: { ok: false, error: "You have reached today's limit. Please try again tomorrow." } };
  }

  const today = londonDate(d.now);
  const v = validate(form, { data: input.data, consent: input.consent }, today);
  if (!v.ok) return { status: 422, body: { ok: false, error: "Please check the form.", errors: v.errors } };

  const data = v.data as Record<string, any>;
  // a trial class runs on one weekday: the chosen day must be that weekday ("HIIT, Wednesday 07:00")
  if (form.id === "trial-class" && data.class && data.date) {
    const wd = String(data.class).match(/, (Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday) \d{2}:\d{2}$/)?.[1];
    const actual = new Intl.DateTimeFormat("en-GB", { timeZone: "UTC", weekday: "long" }).format(new Date(data.date + "T12:00:00Z"));
    if (wd && wd !== actual) return { status: 422, body: { ok: false, error: `That class runs on ${wd}s. Please pick a ${wd}.`, errors: [{ field: "date", message: `That class runs on ${wd}s.` }] } };
  }
  const personEmail: string = data.email ?? ctx.user?.email ?? "";
  const personName: string = data.full_name ?? data.parent_name ?? (ctx.user ? await d.profileName(ctx.user.id) : "") ?? "";

  const id = await d.insertSubmission({
    form_id: form.id, data, consent: v.consent, source_url: v.meta.page_url ?? null,
    utm: { utm_source: v.meta.utm_source, utm_medium: v.meta.utm_medium, utm_campaign: v.meta.utm_campaign }, ip_hash: ctx.ipHash,
    user_id: ctx.user?.id ?? null, delete_after: addDays(today, form.retentionDays ?? 730),
  });

  // consent record (kept with the exact words the person saw)
  const marketingBox = (form.consents ?? []).find((c: any) => c.id === "marketing");
  let sentConfirm = false;
  if (marketingBox && v.consent.marketing && personEmail) {
    const prev = await d.getConsent(personEmail);
    const wording = marketingBox.text;
    if (form.doubleOptIn) {
      if (!(prev?.confirmed_at && !prev?.withdrawn_at)) {
        await d.upsertConsent({ email: personEmail, user_id: ctx.user?.id ?? null, source: form.source, wording, requested_at: d.now.toISOString(), confirmed_at: null, withdrawn_at: null });
        sentConfirm = true;
      }
    } else if (!(prev?.confirmed_at && !prev?.withdrawn_at)) {
      await d.upsertConsent({ email: personEmail, user_id: ctx.user?.id ?? null, source: form.source, wording, requested_at: d.now.toISOString(), confirmed_at: d.now.toISOString(), withdrawn_at: null });
    }
  }

  // emails: best effort, each one on its own
  const tasks: Promise<void>[] = [];
  const safe = (p: Promise<void>) => tasks.push(p.catch((e) => console.error("email failed", form.id, String(e?.message ?? e))));
  const first = firstWord(personName);

  if (sentConfirm) {
    const t = await d.token("confirm", personEmail);
    safe(d.send({ template: "newsletter-welcome", to: personEmail, vars: { first_name: data.first_name ? firstWord(data.first_name) : "there", confirm_url: `${GLOBALS.app_url}email.html?a=confirm&t=${t}` } }));
  }

  const notifyOk = form.notify && (!form.notifyWhen || (form.notifyWhen === "rating <= 3" && Number(data.rating) <= 3));
  if (notifyOk) {
    let vars: Record<string, string>;
    if (form.notify === "admin-change-request") vars = { admin_url: ADMIN_URL, person_name: personName, request_type: data.request_type, from_date: niceDate(data.from_date), reason: data.reason ?? "Not given", sla: "2 working days" };
    else if (form.notify === "admin-new-review") vars = { admin_url: ADMIN_URL, person_name: personName, class_name: data.class ?? "Not said", rating: String(data.rating), message: data.message ?? "No comment" };
    else vars = { admin_url: ADMIN_URL, form_name: form.adminLabel ?? String(form.title).toLowerCase(), person_name: personName, person_email: personEmail, person_phone: data.phone ?? "Not given", message: summary(data), source_page: v.meta.page_url ?? form.where };
    safe(d.send({ template: form.notify, to: ADMIN_EMAIL, vars, replyTo: personEmail || undefined }));
  }

  if (form.autoreply && personEmail) {
    const vars: Record<string, string> = { first_name: first, message_preview: String(data.message ?? summary(data)).slice(0, 140), offer_name: v.meta.offer_name ?? "our offer", offer_terms: "", company: data.company ?? "your company", child_first_name: data.child_first_name ?? "your child" };
    safe(d.send({ template: form.autoreply, to: personEmail, vars }));
  }

  if (form.sendsTo === "referral-invite" && ctx.user && data.friend_email && data.friend_email !== ctx.user.email.toLowerCase()) {
    const refName = firstWord(await d.profileName(ctx.user.id));
    safe(d.send({ template: "referral-invite", to: data.friend_email, vars: { friend_name: firstWord(data.friend_name), referrer_name: refName, referral_url: GLOBALS.app_url }, replyTo: ctx.user.email }));
  }

  await Promise.all(tasks);
  const message = form.successHigh && Number(data.rating) >= 4 ? form.successHigh : form.success;
  return { status: 200, body: { ok: true, id, message } };
}

// ---- function ----
// MY GYM London: receives every website and app form, stores it, records marketing consent and sends the emails.
// Public (Verify JWT off) because website visitors are not signed in; the checks are in logic.ts. Signed-in app forms send the member's token.
// Secrets: RESEND_API_KEY, EMAIL_TOKEN_SECRET (any long random text, 32+ characters). SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are automatic.




const ALLOWED_ORIGINS = [
  "https://app.mygymlondon.co.uk",
  "https://www.mygymlondon.co.uk",
  "https://mygymlondon.co.uk",
  "https://nevespedropt-prog.github.io",
  "http://localhost:8137",
];
const FROM = "MY GYM London <info@mygymlondon.co.uk>";

function cors(req: Request) {
  const origin = req.headers.get("origin") ?? "";
  return {
    "Access-Control-Allow-Origin": ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0],
    "Access-Control-Allow-Headers": "content-type, authorization, apikey, x-client-info",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Vary": "Origin",
  };
}
const json = (req: Request, status: number, body: Record<string, unknown>) =>
  new Response(JSON.stringify(body), { status, headers: { ...cors(req), "Content-Type": "application/json" } });

const sha256 = async (s: string) => Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s)))).map((b) => b.toString(16).padStart(2, "0")).join("");

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: cors(req) });
  if (req.method !== "POST") return json(req, 405, { ok: false, error: "Method not allowed" });
  // browsers only: a cross-site page that is not ours cannot read the answer, and we do not store its submissions
  const origin = req.headers.get("origin");
  if (origin && !ALLOWED_ORIGINS.includes(origin)) return json(req, 403, { ok: false, error: "Not allowed" });

  const secret = Deno.env.get("EMAIL_TOKEN_SECRET") ?? "";
  const resendKey = (Deno.env.get("RESEND_API_KEY") ?? "").replace(/["'\s]/g, "");
  if (secret.length < 32) return json(req, 500, { ok: false, error: "EMAIL_TOKEN_SECRET is not set" });

  let body: Record<string, unknown>;
  try { body = await req.json(); } catch { return json(req, 400, { ok: false, error: "Bad request" }); }

  const url = Deno.env.get("SUPABASE_URL")!;
  const admin = createClient(url, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
  const ip = (req.headers.get("cf-connecting-ip") ?? req.headers.get("x-forwarded-for") ?? "unknown").split(",")[0].trim();
  const ipHash = await sha256(ip + ":" + secret);

  let user: { id: string; email: string } | null = null;
  const bearer = (req.headers.get("authorization") ?? "").replace(/^Bearer\s+/i, "");
  if (bearer) {
    const { data } = await admin.auth.getUser(bearer);   // fails for the public key, which is fine: that means "not signed in"
    if (data?.user?.email) user = { id: data.user.id, email: data.user.email.toLowerCase() };
  }

  const deps: Deps = {
    now: new Date(),
    countByIp: async (formId, h, since) => (await admin.from("form_submissions").select("id", { count: "exact", head: true }).eq("form_id", formId).eq("ip_hash", h).gte("created_at", since)).count ?? 0,
    countByUser: async (formId, uid, since) => (await admin.from("form_submissions").select("id", { count: "exact", head: true }).eq("form_id", formId).eq("user_id", uid).gte("created_at", since)).count ?? 0,
    insertSubmission: async (row) => {
      const { data, error } = await admin.from("form_submissions").insert(row).select("id").single();
      if (error) throw new Error("store_failed");
      return data.id as string;
    },
    upsertConsent: async (row) => { const { error } = await admin.from("marketing_consent").upsert(row, { onConflict: "email" }); if (error) throw new Error("consent_failed"); },
    getConsent: async (email) => (await admin.from("marketing_consent").select("confirmed_at, withdrawn_at").eq("email", email).maybeSingle()).data ?? null,
    profileName: async (uid) => ((await admin.from("profiles").select("full_name").eq("id", uid).maybeSingle()).data?.full_name as string) ?? "",
    token: async (purpose, email) => makeToken(secret, purpose, email),
    send: async ({ template, to, vars, replyTo }) => {
      if (!resendKey) throw new Error("RESEND_API_KEY not set");
      const mail = render(template, vars);
      const r = await fetch("https://api.resend.com/emails", {
        method: "POST",
        headers: { Authorization: `Bearer ${resendKey}`, "Content-Type": "application/json" },
        body: JSON.stringify({ from: FROM, to: [to], reply_to: replyTo ?? "info@mygymlondon.co.uk", subject: mail.subject, text: mail.text, html: mail.html }),
      });
      if (!r.ok) throw new Error("resend_" + r.status);
    },
  };

  try {
    const result = await processSubmission(body as never, { ipHash, user, functionsUrl: `${url}/functions/v1` }, deps);
    return json(req, result.status, result.body);
  } catch (e) {
    console.error("submit-form failed", String((e as Error)?.message ?? e));
    return json(req, 500, { ok: false, error: "Something went wrong. Please try again or email info@mygymlondon.co.uk." });
  }
});
